// collector-pipelines.spec.ts — F-CONTRIB (#423): the collector page's
// Pipelines tab lists the pipelines its served config is built from (link,
// matcher evidence, lines in the served text) and the matched pipelines that
// were excluded, with the reason — all from GetServedConfig.
import { expect } from '@playwright/test';
import { basicScenario, collector } from '../fixtures/factories';
import { viewer } from '../fixtures/personas';
import { test } from '../fixtures/test';

const content = [
  '// Generated by Shepherd',
  '// Collector: prod/metrics (col-contrib-1)',
  '// Pipelines (1):',
  '//   - app-metrics (rev 3)',
  '// Excluded (1) - signal/role mismatch (docs/gateway-tier-plan.md W1, gate G6):',
  '//   - pod-logs: role metrics does not allow logs',
  '',
  'declare "pipe_app_metrics" {',
  '  prometheus.scrape "app" {',
  '    targets    = []',
  '    forward_to = []',
  '  }',
  '}',
  'pipe_app_metrics "default" { }',
  '',
  '// Shepherd self-monitoring baseline',
  'prometheus.exporter.self "shepherd_beacon" { }',
  '',
].join('\n');

const provenance = {
  content,
  hash: 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855',
  provenance_recorded: true,
  contributing: [
    {
      pipeline_id: 'pipe-app-metrics',
      name: 'app-metrics',
      revision: 3,
      source: 'ui',
      matchers: [
        { matcher: 'cluster="prod"', label: 'cluster', value: 'prod', present: true },
        { matcher: 'env!="dev"', label: 'env', value: '', present: false },
      ],
      lines: { first: 8, last: 14 },
      block_name: 'pipe_app_metrics',
    },
  ],
  excluded: [
    {
      pipeline_id: 'pipe-pod-logs',
      name: 'pod-logs',
      reason: 'role',
      message: 'its signals (logs) are not allowed on role metrics',
      disallowed_signals: ['logs'],
    },
    {
      pipeline_id: 'pipe-strict',
      name: 'strict-otlp',
      reason: 'strict_tenant',
      message: '3:5 tenant "acme-other" is not one this org owns',
    },
  ],
  baseline_lines: { first: 16, last: 17 },
};

test('the Pipelines tab lists contributing and excluded pipelines with their evidence', async ({
  page,
  api,
}) => {
  await api.loginAs(viewer);
  const s = basicScenario();
  const c = collector({ id: 'col-contrib-1', role: 'metrics' });
  api.seed({ orgs: [s.org], collectors: [c], servedConfig: provenance });

  await page.goto(`/collectors/${c.id}`);
  await page.getByRole('button', { name: 'Pipelines', exact: true }).click();

  const contributing = page.getByRole('table', { name: /Contributing/ });
  await expect(contributing).toBeVisible();
  const row = contributing.getByTestId('contributing-row');
  await expect(row).toHaveCount(1);
  await expect(row.getByRole('link', { name: 'app-metrics' })).toHaveAttribute(
    'href',
    '/pipelines/pipe-app-metrics',
  );
  await expect(row).toContainText('rev 3');
  await expect(row).toContainText('cluster="prod"');
  await expect(row).toContainText('cluster is "prod"');
  await expect(row).toContainText('env is not set');
  await expect(row.getByTestId('contributing-lines')).toHaveText('Lines 8–14');

  const baseline = contributing.getByTestId('baseline-row');
  await expect(baseline).toContainText('Self-monitoring baseline');
  await expect(baseline).toContainText('Lines 16–17');

  const excluded = page.getByRole('table', { name: /Excluded/ });
  const rows = excluded.getByTestId('excluded-row');
  await expect(rows).toHaveCount(2);
  await expect(rows.nth(0).getByRole('link', { name: 'pod-logs' })).toHaveAttribute(
    'href',
    '/pipelines/pipe-pod-logs',
  );
  await expect(rows.nth(0).getByTestId('excluded-reason')).toHaveText('Role');
  await expect(rows.nth(0)).toContainText('its signals (logs) are not allowed on role metrics');
  await expect(rows.nth(1).getByTestId('excluded-reason')).toHaveText('Strict tenant check');
  await expect(rows.nth(1)).toContainText('tenant "acme-other" is not one this org owns');
});

test("a contributor's lines open the served config with its block highlighted", async ({
  page,
  api,
}) => {
  await api.loginAs(viewer);
  const s = basicScenario();
  const c = collector({ id: 'col-contrib-1', role: 'metrics' });
  api.seed({ orgs: [s.org], collectors: [c], servedConfig: provenance });

  await page.goto(`/collectors/${c.id}`);
  await page.getByRole('button', { name: 'Pipelines', exact: true }).click();
  await page.getByTestId('contributing-row').getByTestId('contributing-lines').click();

  await expect(page.getByTestId('served-config-highlight')).toContainText(
    'Highlighting lines 8–14 — app-metrics',
  );
  const marked = page.getByTestId('served-config-text').locator('mark');
  await expect(marked).toHaveCount(7);
  await expect(marked.first()).toHaveText('declare "pipe_app_metrics" {\n');
  await expect(marked.last()).toHaveText('pipe_app_metrics "default" { }\n');
  // The served text itself is unchanged by the highlight.
  await expect(page.getByTestId('served-config-text')).toHaveText(content);

  await page.getByRole('button', { name: 'Clear' }).click();
  await expect(marked).toHaveCount(0);
});

// 0.21.0-rc.1 walkthrough: the highlight was page state only, so a "Lines
// N–M" view could not be linked to. It is now in the URL.
test('a served-config highlight is addressable in the URL', async ({ page, api }) => {
  await api.loginAs(viewer);
  const s = basicScenario();
  const c = collector({ id: 'col-contrib-1', role: 'metrics' });
  api.seed({ orgs: [s.org], collectors: [c], servedConfig: provenance });

  // The button puts the highlight in the URL…
  await page.goto(`/collectors/${c.id}`);
  await page.getByRole('button', { name: 'Pipelines', exact: true }).click();
  await page.getByTestId('contributing-row').getByTestId('contributing-lines').click();
  await expect(page).toHaveURL(/[?&]tab=config(&|$)/);
  await expect(page).toHaveURL(/[?&]lines=8-14(&|$)/);

  // …and opening that URL highlights the block, named from the provenance.
  await page.goto(`/collectors/${c.id}?tab=config&lines=8-14`);
  await expect(page.getByTestId('served-config-highlight')).toContainText(
    'Highlighting lines 8–14 — app-metrics',
  );
  const marked = page.getByTestId('served-config-text').locator('mark');
  await expect(marked).toHaveCount(7);
  await expect(marked.first()).toBeInViewport();

  // Clear drops it from the URL; a tab link opens that tab.
  await page.getByRole('button', { name: 'Clear' }).click();
  await expect(marked).toHaveCount(0);
  await expect(page).not.toHaveURL(/lines=/);
  await page.goto(`/collectors/${c.id}?tab=pipelines`);
  await expect(page.getByTestId('contributing-row')).toBeVisible();
  // A range that is not one is ignored.
  await page.goto(`/collectors/${c.id}?tab=config&lines=14-8`);
  await expect(page.getByTestId('served-config-text')).toBeVisible();
  await expect(page.getByTestId('served-config-highlight')).toHaveCount(0);
});

test('the Pipelines tab shows empty states, and says when provenance is not recorded yet', async ({
  page,
  api,
}) => {
  await api.loginAs(viewer);
  const s = basicScenario();
  const c = collector({ id: 'col-contrib-2', role: 'metrics' });
  api.seed({
    orgs: [s.org],
    collectors: [c],
    servedConfig: {
      content: '// Generated by Shepherd\n// No pipelines matched\n',
      hash: 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855',
      provenance_recorded: true,
    },
  });
  await page.goto(`/collectors/${c.id}`);
  await page.getByRole('button', { name: 'Pipelines', exact: true }).click();
  await expect(page.getByTestId('contributing-empty')).toBeVisible();
  await expect(page.getByTestId('excluded-empty')).toBeVisible();
  await expect(page.getByRole('table')).toHaveCount(0);

  api.seed({
    servedConfig: {
      content: '// Generated by Shepherd\n',
      hash: 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855',
    },
  });
  await page.reload();
  await page.getByRole('button', { name: 'Pipelines', exact: true }).click();
  await expect(page.getByTestId('provenance-not-recorded')).toBeVisible();
});
